lab = np.load(WORK/'labels.npy'); N=len(lab); folds=np.load(WORK/'folds.npy'); Y=np.eye(8)[lab]
M=np.load(WORK/'base_mean.npy')
def fit_ridge(Xt,Yt,lam):
    mu=Xt.mean(0); sd=Xt.std(0)+1e-6; Z=(Xt-mu)/sd
    W=np.linalg.solve(Z.T@Z+lam*np.eye(Z.shape[1]), Z.T@(Yt-Yt.mean(0)))
    return lambda X: ((X-mu)/sd)@W
oof={}
for l in range(13):
    for lam in [100,300]:
        o=np.zeros((N,8))
        for f in range(5):
            tr=folds!=f; te=~tr
            o[te]=fit_ridge(M[l][tr],Y[tr],lam)(M[l][te])
        oof[(l,lam)]=o
np.save(WORK/'oof_ridge.npy', np.stack([oof[(l,300)] for l in range(13)]))
acc=lambda S:(S.argmax(1)==lab).mean()
for l in range(13): print(l, round(acc(oof[(l,100)]),4), round(acc(oof[(l,300)]),4))
print('fusion pairs with 11 (lam 300 early, 100 late):')
for l in range(0,11):
    print(l, [round(acc(w*oof[(l,300)]+oof[(11,100)]),4) for w in [0.5,1,1.5]])
for combo in [(1,6),(2,6),(1,5),(2,5),(1,4),(2,8),(1,8),(0,6)]:
    print(combo, round(acc(oof[(combo[0],300)]+oof[(combo[1],300)]+oof[(11,100)]),4))
